/// <summary>
///     Data Contract class for <c>AVASalesRouteCardReport</c> SSRS report
/// </summary>
/// <remarks>
///     This is the Data Contract class for the <c>AVAInventTransferJour</c> SSRS Report.
/// </remarks>
[
    DataContractAttribute
]
    public class AVAInventTransferJourContract
{
    CreatedTransactionId        contractCreatedTransactionId;
    RefRecId                    contractInventTransferJourRefRecId;
    InventTransferId            contractTransferId;
    InventTransferVoucherId     contractVoucherId;
    TransDate                   contractTransDate;
    InventTransferUpdateType    contractUpdateType;

    boolean                     contractInventConfigId;
    boolean                     contractInventSiteId;
    boolean                     contractInventLocationId;
    boolean                     contractInventColorId;
    boolean                     contractInventSizeId;
    boolean                     contractInventStyleId;
    boolean                     contractInventBatchId;
    boolean                     contractInventSerialId;
    boolean                     contractWMSLocationId;


}

